#include  "c6x_syscall.H"

void* c6x::dispatch() {
  if( ac_pc >= dec_cache_size){
    cerr << "ArchC: Address out of bounds (pc=0x" << hex << ac_pc << ")." << endl;
    stop();
    longjmp(ac_env, AC_ACTION_STOP);
  }
  ac_instr_counter++;
  unsigned ins_id;
  instr_dec = (DEC_CACHE + (ac_pc / 4));
  if ( !instr_dec->valid ){
    unsigned* ins_cache;
    decode_pc = ac_pc;
    quant = 0;
    ins_cache = (ISA.decoder)->Decode(reinterpret_cast<unsigned char*>(buffer), quant);
    instr_dec->valid = true;
    instr_dec->id = ins_cache ? ins_cache[IDENT]: 0;
    instr_dec->end_rot = IntRoutine[instr_dec->id];
    switch (ISA.instr_format_table[instr_dec->id]) {
      case 1:
        instr_dec->F_Type_VLIW_Reg.creg = ins_cache[1];
        instr_dec->F_Type_VLIW_Reg.z = ins_cache[2];
        instr_dec->F_Type_VLIW_Reg.op = ins_cache[3];
        instr_dec->F_Type_VLIW_Reg.src2 = ins_cache[4];
        instr_dec->F_Type_VLIW_Reg.src1 = ins_cache[5];
        instr_dec->F_Type_VLIW_Reg.dst = ins_cache[6];
        instr_dec->F_Type_VLIW_Reg.pad = ins_cache[7];
        instr_dec->F_Type_VLIW_Reg.s = ins_cache[8];
        instr_dec->F_Type_VLIW_Reg.p = ins_cache[9];
      break;
      case 2:
        instr_dec->F_Type_VLIW_Imm.creg = ins_cache[1];
        instr_dec->F_Type_VLIW_Imm.z = ins_cache[2];
        instr_dec->F_Type_VLIW_Imm.op = ins_cache[3];
        instr_dec->F_Type_VLIW_Imm.cst = ins_cache[10];
        instr_dec->F_Type_VLIW_Imm.dst = ins_cache[11];
      break;
      case 3:
        instr_dec->F_Type_Branch.creg = ins_cache[1];
        instr_dec->F_Type_Branch.z = ins_cache[2];
        instr_dec->F_Type_Branch.op = ins_cache[3];
        instr_dec->F_Type_Branch.disp = ins_cache[12];
      break;
      case 4:
        instr_dec->F_Type_Halt.op = ins_cache[13];
        instr_dec->F_Type_Halt.pad = ins_cache[14];
      break;
      default:
        cerr << "ArchC Error: Unidentified instruction. " << endl;
        cerr << "PC = " << hex << ac_pc << dec << endl;
        stop();
        longjmp(ac_env, AC_ACTION_STOP);
    }
  }
  ins_id = instr_dec->id;

  return instr_dec->end_rot;
}

